114:     function executePayload(address target, string memory signature, bytes memory data) public returns (bytes memory) {
115:         require(msg.sender == address(this), "Timelock::executePayload: Call must come from Timelock.");
116:         bytes memory callData;
117: 
118:         if (bytes(signature).length == 0) {
119:             callData = data;
120:         } else {
121:             callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
122:         }
123: 
124:         // solium-disable-next-line security/no-call-value
125:         (bool success, bytes memory returnData) = target.delegatecall(callData);
126:         require(success, "Timelock::executePayload: Transaction execution reverted.");
127: 
128:         return returnData;
129:     }
130: 
131:     function getBlockTimestamp() internal view returns (uint) {
132:         // solium-disable-next-line security/no-block-members
133:         return block.timestamp;
134:     }
135: }
